import { useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded' | 'paused';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_CONFIG: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  active: { label: 'Активен', tone: 'success' },
  warning: { label: 'На пределе', tone: 'warning' },
  exceeded: { label: 'Превышен', tone: 'danger' },
  paused: { label: 'Приостановлен', tone: 'info' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Мобильное приложение «Курьер»', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Внутренний портал HR', quotaPercent: 88, status: 'warning' },
  { id: 'p3', name: 'Аналитика продаж Q3', quotaPercent: 100, status: 'exceeded' },
  { id: 'p4', name: 'Редизайн лендинга', quotaPercent: 15, status: 'active' },
  { id: 'p5', name: 'Интеграция с 1С', quotaPercent: 60, status: 'paused' },
  { id: 'p6', name: 'Чат-бот поддержки', quotaPercent: 95, status: 'warning' },
  { id: 'p7', name: 'Миграция на новый CDN', quotaPercent: 30, status: 'active' },
  { id: 'p8', name: 'Платёжный шлюз v2', quotaPercent: 110, status: 'exceeded' },
  { id: 'p9', name: 'Архив документов', quotaPercent: 5, status: 'paused' },
  { id: 'p10', name: 'CRM для отдела продаж', quotaPercent: 70, status: 'active' },
  { id: 'p11', name: 'Логистический трекер', quotaPercent: 82, status: 'warning' },
  { id: 'p12', name: 'Личный кабинет клиента', quotaPercent: 25, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses([]);
    setPage(1);
  };

  const filtered =
    selectedStatuses.length === 0
      ? PROJECTS
      : PROJECTS.filter((p) => selectedStatuses.includes(p.status));

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '640px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {(Object.keys(STATUS_CONFIG) as ProjectStatus[]).map((status) => {
          const isActive = selectedStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_CONFIG[status].label}
            </JxChip>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderRadius: 'var(--jx-r)',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                }}
              >
                <span style={{ flex: 1, color: 'var(--jx-text)' }}>{project.name}</span>
                <JxProgressCircle value={Math.min(project.quotaPercent, 100)} showValue />
                <JxBadge tone={STATUS_CONFIG[project.status].tone}>
                  {STATUS_CONFIG[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

